module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

	reg [2:0] counter;
	reg [23:0] a_mantissa, b_mantissa, z_mantissa;
	reg [9:0] a_exponent, b_exponent, z_exponent;
	reg a_sign, b_sign, z_sign;
	reg guard_bit, round_bit, sticky;
	reg [49:0] product;
	wire [23:0] temp_a_mantissa, temp_b_mantissa;

	assign temp_a_mantissa[22:0] = a[22:0];
	assign temp_a_mantissa[23] = 1'b1;
	assign temp_b_mantissa[22:0] = b[22:0];
	assign temp_b_mantissa[23] = 1'b1;

	always@(posedge clk) begin
		if(rst == 1'b1)begin
			counter <= 3'd0;
		end else begin
			case(counter)

				0:begin
					a_mantissa[23] <= 1'b1;
					b_mantissa[23] <= 1'b1;
					a_exponent <= {1'b0,a[30:23]};
					b_exponent <= {1'b0,b[30:23]};
					a_sign <= a[31];
					b_sign <= b[31];
					product <= 49'b0;
					counter <= counter + 1'b1;
				end

				1:begin
					if((a_exponent == 10'h1ff && a_mantissa != 0)||(b_exponent == 10'h1ff && b_mantissa != 0))begin 
						z_exponent <= 8'hff;
						z_mantissa <= 23'h1;
						z_sign <= 1'b0;
					end else if(a_exponent == 10'h1ff || b_exponent == 10'h1ff)begin 
						z_exponent <= 10'h1ff;
						z_mantissa <= 23'h0;
						z_sign <= a_sign ^ b_sign;
					end else if(a[30:0]==0||b[30:0]==0)begin 
						z_exponent <= 10'h0;
						z_mantissa <= 23'h0;
						z_sign <= a_sign ^ b_sign;
					end else begin
						product <= {{(a_exponent)},temp_a_mantissa} * {{(b_exponent)},temp_b_mantissa};
						z_exponent <= a_exponent + b_exponent;
						z_sign <= a_sign^b_sign;
						counter <= counter+1'b1;
					end
				end

				2:begin
					if(product[49])begin 
						a_mantissa <= product[48:25]; 
						b_mantissa <= product[24:3];
						z_exponent <= z_exponent + 1'b1;
					end else begin 
						a_mantissa <= product[47:24]; 
						b_mantissa <= product[23:2];
						guard_bit <= product[1];
						round_bit <= product[0];
						sticky <= product[23:2]|guard_bit|round_bit;
						counter <= counter+1'b1;
					end
				end

				3:begin
					product <= a_mantissa*b_mantissa;
					z_exponent <= z_exponent + 1'b1;
					counter <= counter + 1'b1;
				end

				4:begin
					if(guard_bit&(round_bit|sticky|z_mantissa[0]))begin
						z_mantissa <= z_mantissa+1'b1;
						if(z_mantissa==23'hffffff)begin
							z_exponent <= z_exponent + 1'b1;
						end
					end
					counter <= counter + 1'b1;
				end

				5:begin
					if(z_exponent >= 10'h1fe)begin 
						z_exponent <= 10'h1ff;
						z_mantissa <= 23'h0;
						z_sign <= a_sign^b_sign;
					end else if(z_exponent<=10'h01&&z_mantissa!=23'h0)begin 
						z_exponent <= 10'h00;
						z_mantissa <= 23'h0;
						z_sign <= a_sign^b_sign;
					end

					counter <= counter + 1'b1;
				end

				default:begin
					z[22:0] <= z_mantissa;
					z[30:23] <= z_exponent[7:0];
					z[31] <= z_sign;
				end
			endcase
		end

	end
endmodule
